function outOfOrder(heights: number[]): number {
  const count = new Array(101).fill(0);
  for (const h of heights) count[h]++;
  let h = 1, diff = 0;
  for (const actual of heights) {
    while (count[h] === 0) h++;
    if (actual !== h) diff++;
    count[h]--;
  }
  return diff;
}

